package llmverify
import chisel3._
import chisel3.util._
import chiselFv._

class luckySeven extends Module with Formal {
  val io = IO(new Bundle {
    val from = Input(UInt(3.W))
    val to = Input(UInt(3.W))
    // Add outputs to preserve the design
    val b_out = Output(Vec(8, UInt(3.W)))
    val valid_out = Output(Bool())
    val permutation_out = Output(Bool())
  })

  // Internal registers
  val b = RegInit(VecInit(Seq.tabulate(8)(i => i.U(3.W))))
  val freg = RegInit(0.U(3.W))
  val treg = RegInit(0.U(3.W))

  // Latch inputs on clock edge
  freg := io.from
  treg := io.to

  // Valid move predicate
  val cond1 = (treg === (freg + 1.U))
  val cond2 = (freg === (treg + 1.U))
  val cond3 = (treg(1,0) === 0.U && freg(1,0) === 0.U && freg(2) =/= treg(2))
  val valid = (b(treg) === 0.U) && (cond1 || cond2 || cond3)

  // Permutation check ensures all board values are unique
  val permutation = b(0) =/= b(1) && b(0) =/= b(2) && b(0) =/= b(3) &&
    b(0) =/= b(4) && b(0) =/= b(5) && b(0) =/= b(6) && b(0) =/= b(7) &&
    b(1) =/= b(2) && b(1) =/= b(3) && b(1) =/= b(4) && b(1) =/= b(5) &&
    b(1) =/= b(6) && b(1) =/= b(7) && b(2) =/= b(3) && b(2) =/= b(4) &&
    b(2) =/= b(5) && b(2) =/= b(6) && b(2) =/= b(7) && b(3) =/= b(4) &&
    b(3) =/= b(5) && b(3) =/= b(6) && b(3) =/= b(7) && b(4) =/= b(5) &&
    b(4) =/= b(6) && b(4) =/= b(7) && b(5) =/= b(6) && b(5) =/= b(7) &&
    b(6) =/= b(7)

  // Perform move if valid
  when(valid) {
    b(treg) := b(freg)
    b(freg) := 0.U
  }

  // Connect outputs
  io.b_out := b
  io.valid_out := valid
  io.permutation_out := permutation

  // ========== Formal Verification Assertions ==========

  // 1. Mutex: The three move sub-conditions are mutually exclusive.
  //    At most one of (adjacent-right, adjacent-left, or row-jump) holds at any time.
  assertMutex(Seq(cond1, cond2, cond3), "move_conditions_mutex")

  // 2. Safety/Invariant: The board values always form a permutation of 0..7.
  //    All 8 entries are distinct in every reachable state.
  fvAssert(permutation, "board_values_always_distinct")

  // 3. Bounded Liveness: A valid move produces a board state change within 2 cycles.
  //    When valid is true, the board's flattened value differs from its previous-cycle
  //    value within 1-2 cycles, ensuring the move is not stuck.
  val prevB = RegNext(b.asUInt())
  val boardChanged = (b.asUInt() =/= prevB)
  astRelaxedLiveness(valid, boardChanged, 2, "valid_move_changes_board")
}

object VerilogGenerator extends App {
  emitVerilog(new luckySeven(), args)
}

